// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library NodeEconomyTypes {
    enum NodeClass {
        Storage,
        Execution,
        Indexing,
        Research
    }

    enum NodeStatus {
        Inactive,
        Active,
        Suspended,
        Decommissioned
    }

    enum SlashReason {
        Downtime,
        InvalidData,
        MissedAttestation,
        SecurityBreach,
        QualityFailure
    }

    struct NodeInfo {
        uint256 nodeId;
        address operator;
        NodeClass nodeClass;
        NodeStatus status;
        uint256 stakeAmount;
        uint256 activatedAt;
        uint256 lastActiveAt;
        bytes32 metadataHash;
        uint256 totalRewardsEarned;
        uint256 slashCount;
    }

    struct StakeRequirement {
        uint256 minStake;
        uint256 lockPeriod;
        bool active;
    }

    struct RewardConfig {
        uint256 baseRewardPerEpoch;
        uint256 performanceMultiplierBps;
        uint256 epochDuration;
        bool active;
    }

    struct SlashingParams {
        uint256 slashPercentBps;
        uint256 cooldownPeriod;
        uint256 maxSlashesBeforeSuspension;
        bool active;
    }

    struct EpochReward {
        uint256 epochId;
        uint256 totalRewards;
        uint256 nodesRewarded;
        uint256 timestamp;
    }

    struct SlashEvent {
        uint256 slashId;
        uint256 nodeId;
        SlashReason reason;
        uint256 amount;
        address slasher;
        uint256 timestamp;
        bytes32 evidenceHash;
    }

    struct PerformanceMetrics {
        uint256 uptimeBps;
        uint256 tasksCompleted;
        uint256 qualityScore;
        uint256 lastUpdated;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./NodeEconomyTypes.sol";
import "./INodeEconomy.sol";

contract NodeRegistry is INodeRegistry, AccessControl, ReentrancyGuard, Pausable {
    using NodeEconomyTypes for *;

    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant NODE_MANAGER_ROLE = keccak256("NODE_MANAGER_ROLE");
    bytes32 public constant SLASHER_ROLE = keccak256("SLASHER_ROLE");

    uint256 private _nextNodeId = 1;

    mapping(uint256 => NodeEconomyTypes.NodeInfo) private _nodes;
    mapping(address => uint256[]) private _operatorNodes;
    mapping(NodeEconomyTypes.NodeClass => NodeEconomyTypes.StakeRequirement) private _stakeRequirements;
    mapping(NodeEconomyTypes.NodeClass => uint256) private _activeNodeCounts;
    mapping(uint256 => uint256) private _lockExpiresAt;

    address public rewardsContract;
    address public slashingContract;
    bool private _contractsConfigured;

    event SlashedFundsTransferred(uint256 indexed nodeId, uint256 amount, address indexed slashingEngine);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GUARDIAN_ROLE, admin);

        _stakeRequirements[NodeEconomyTypes.NodeClass.Storage] = NodeEconomyTypes.StakeRequirement({
            minStake: 0.1 ether,
            lockPeriod: 30 days,
            active: true
        });
        _stakeRequirements[NodeEconomyTypes.NodeClass.Execution] = NodeEconomyTypes.StakeRequirement({
            minStake: 0.5 ether,
            lockPeriod: 60 days,
            active: true
        });
        _stakeRequirements[NodeEconomyTypes.NodeClass.Indexing] = NodeEconomyTypes.StakeRequirement({
            minStake: 0.25 ether,
            lockPeriod: 30 days,
            active: true
        });
        _stakeRequirements[NodeEconomyTypes.NodeClass.Research] = NodeEconomyTypes.StakeRequirement({
            minStake: 1 ether,
            lockPeriod: 90 days,
            active: true
        });
    }

    function setContracts(address _rewards, address _slashing) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(!_contractsConfigured, "Contracts already configured");
        require(_rewards != address(0), "Invalid rewards address");
        require(_slashing != address(0), "Invalid slashing address");

        rewardsContract = _rewards;
        slashingContract = _slashing;
        _contractsConfigured = true;
    }

    function setStakeRequirement(
        NodeEconomyTypes.NodeClass nodeClass,
        uint256 minStake,
        uint256 lockPeriod
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _stakeRequirements[nodeClass] = NodeEconomyTypes.StakeRequirement({
            minStake: minStake,
            lockPeriod: lockPeriod,
            active: true
        });
        emit StakeRequirementUpdated(nodeClass, minStake, lockPeriod);
    }

    function registerNode(
        NodeEconomyTypes.NodeClass nodeClass,
        bytes32 metadataHash
    ) external whenNotPaused returns (uint256) {
        require(metadataHash != bytes32(0), "Invalid metadata");
        require(_stakeRequirements[nodeClass].active, "Node class not active");

        uint256 nodeId = _nextNodeId++;

        _nodes[nodeId] = NodeEconomyTypes.NodeInfo({
            nodeId: nodeId,
            operator: msg.sender,
            nodeClass: nodeClass,
            status: NodeEconomyTypes.NodeStatus.Inactive,
            stakeAmount: 0,
            activatedAt: 0,
            lastActiveAt: 0,
            metadataHash: metadataHash,
            totalRewardsEarned: 0,
            slashCount: 0
        });

        _operatorNodes[msg.sender].push(nodeId);

        emit NodeRegistered(nodeId, msg.sender, nodeClass);
        return nodeId;
    }

    function activateNode(uint256 nodeId) external payable nonReentrant whenNotPaused {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.operator == msg.sender, "Not operator");
        require(node.status == NodeEconomyTypes.NodeStatus.Inactive, "Node not inactive");

        NodeEconomyTypes.StakeRequirement memory req = _stakeRequirements[node.nodeClass];
        uint256 totalStake = node.stakeAmount + msg.value;
        require(totalStake >= req.minStake, "Insufficient stake");

        node.stakeAmount = totalStake;
        node.status = NodeEconomyTypes.NodeStatus.Active;
        node.activatedAt = block.timestamp;
        node.lastActiveAt = block.timestamp;

        _lockExpiresAt[nodeId] = block.timestamp + req.lockPeriod;

        _activeNodeCounts[node.nodeClass]++;

        emit NodeActivated(nodeId, totalStake);
    }

    function deactivateNode(uint256 nodeId) external nonReentrant {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.operator == msg.sender, "Not operator");
        require(node.status == NodeEconomyTypes.NodeStatus.Active, "Node not active");

        node.status = NodeEconomyTypes.NodeStatus.Inactive;
        _activeNodeCounts[node.nodeClass]--;

        emit NodeDeactivated(nodeId);
    }

    function suspendNode(uint256 nodeId, string calldata reason) external onlyRole(SLASHER_ROLE) {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.status == NodeEconomyTypes.NodeStatus.Active, "Node not active");

        node.status = NodeEconomyTypes.NodeStatus.Suspended;
        _activeNodeCounts[node.nodeClass]--;

        emit NodeSuspended(nodeId, reason);
    }

    function reactivateNode(uint256 nodeId) external onlyRole(NODE_MANAGER_ROLE) {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.status == NodeEconomyTypes.NodeStatus.Suspended, "Node not suspended");

        NodeEconomyTypes.StakeRequirement memory req = _stakeRequirements[node.nodeClass];
        require(node.stakeAmount >= req.minStake, "Insufficient stake after slash");

        node.status = NodeEconomyTypes.NodeStatus.Active;
        node.lastActiveAt = block.timestamp;
        node.activatedAt = block.timestamp;
        _lockExpiresAt[nodeId] = block.timestamp + req.lockPeriod;

        _activeNodeCounts[node.nodeClass]++;

        emit NodeActivated(nodeId, node.stakeAmount);
    }

    function decommissionNode(uint256 nodeId) external {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.operator == msg.sender || hasRole(GUARDIAN_ROLE, msg.sender), "Not authorized");
        require(node.status != NodeEconomyTypes.NodeStatus.Active, "Deactivate first");

        node.status = NodeEconomyTypes.NodeStatus.Decommissioned;

        emit NodeDecommissioned(nodeId);
    }

    function updateMetadata(uint256 nodeId, bytes32 metadataHash) external {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.operator == msg.sender, "Not operator");
        require(metadataHash != bytes32(0), "Invalid metadata");

        node.metadataHash = metadataHash;

        emit MetadataUpdated(nodeId, metadataHash);
    }

    function withdrawStake(uint256 nodeId) external nonReentrant {
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.operator == msg.sender, "Not operator");
        require(node.status == NodeEconomyTypes.NodeStatus.Inactive || 
                node.status == NodeEconomyTypes.NodeStatus.Decommissioned, "Must be inactive");

        require(block.timestamp >= _lockExpiresAt[nodeId], "Lock period active");

        uint256 amount = node.stakeAmount;
        require(amount > 0, "No stake");

        node.stakeAmount = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");

        emit StakeUpdated(nodeId, amount, 0);
    }

    function reduceStakeAndTransfer(uint256 nodeId, uint256 amount) external onlyRole(SLASHER_ROLE) nonReentrant {
        require(slashingContract != address(0), "Slashing not configured");
        require(msg.sender == slashingContract, "Only slashing contract");

        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");
        require(node.stakeAmount >= amount, "Insufficient stake");

        uint256 oldAmount = node.stakeAmount;
        node.stakeAmount -= amount;
        node.slashCount++;

        (bool success, ) = slashingContract.call{value: amount}("");
        require(success, "Transfer to slashing failed");

        emit StakeUpdated(nodeId, oldAmount, node.stakeAmount);
        emit SlashedFundsTransferred(nodeId, amount, slashingContract);
    }

    function reduceStake(uint256 nodeId, uint256 amount) external onlyRole(SLASHER_ROLE) {
        revert("Use reduceStakeAndTransfer instead");
    }

    function recordReward(uint256 nodeId, uint256 amount) external {
        require(_contractsConfigured, "Contracts not configured");
        require(msg.sender == rewardsContract, "Not rewards contract");
        NodeEconomyTypes.NodeInfo storage node = _nodes[nodeId];
        require(node.nodeId != 0, "Node not found");

        node.totalRewardsEarned += amount;
        node.lastActiveAt = block.timestamp;
    }

    function getNode(uint256 nodeId) external view returns (NodeEconomyTypes.NodeInfo memory) {
        require(_nodes[nodeId].nodeId != 0, "Node not found");
        return _nodes[nodeId];
    }

    function getNodesByOperator(address operator) external view returns (uint256[] memory) {
        return _operatorNodes[operator];
    }

    function getActiveNodeCount(NodeEconomyTypes.NodeClass nodeClass) external view returns (uint256) {
        return _activeNodeCounts[nodeClass];
    }

    function isNodeActive(uint256 nodeId) external view returns (bool) {
        return _nodes[nodeId].status == NodeEconomyTypes.NodeStatus.Active;
    }

    function getStakeRequirement(NodeEconomyTypes.NodeClass nodeClass) external view returns (NodeEconomyTypes.StakeRequirement memory) {
        return _stakeRequirements[nodeClass];
    }

    function getLockExpiry(uint256 nodeId) external view returns (uint256) {
        return _lockExpiresAt[nodeId];
    }

    function getTotalNodeCount() external view returns (uint256) {
        return _nextNodeId - 1;
    }

    function areContractsConfigured() external view returns (bool) {
        return _contractsConfigured;
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(GUARDIAN_ROLE) {
        _unpause();
    }

    receive() external payable {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./NodeEconomyTypes.sol";
import "./INodeEconomy.sol";

interface INodeRegistryForRewards {
    function getNode(uint256 nodeId) external view returns (NodeEconomyTypes.NodeInfo memory);
    function isNodeActive(uint256 nodeId) external view returns (bool);
    function recordReward(uint256 nodeId, uint256 amount) external;
    function getActiveNodeCount(NodeEconomyTypes.NodeClass nodeClass) external view returns (uint256);
}

contract NodeRewards is INodeRewards, AccessControl, ReentrancyGuard, Pausable {
    using NodeEconomyTypes for *;

    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 public constant REWARDS_MANAGER_ROLE = keccak256("REWARDS_MANAGER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    INodeRegistryForRewards public nodeRegistry;

    uint256 public currentEpoch;
    uint256 public epochStartTime;
    uint256 public globalEpochDuration;
    uint256 public maxRewardsPerEpoch;

    mapping(NodeEconomyTypes.NodeClass => NodeEconomyTypes.RewardConfig) private _rewardConfigs;
    mapping(uint256 => NodeEconomyTypes.PerformanceMetrics) private _nodePerformance;
    mapping(uint256 => uint256) private _pendingRewards;
    mapping(uint256 => NodeEconomyTypes.EpochReward) private _epochRewards;
    mapping(uint256 => mapping(uint256 => bool)) private _epochNodeRewarded;

    constructor(address admin, address _nodeRegistry) {
        require(_nodeRegistry != address(0), "Invalid registry");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(GUARDIAN_ROLE, admin);

        nodeRegistry = INodeRegistryForRewards(_nodeRegistry);
        currentEpoch = 1;
        epochStartTime = block.timestamp;
        globalEpochDuration = 7 days;
        maxRewardsPerEpoch = 10 ether;

        _rewardConfigs[NodeEconomyTypes.NodeClass.Storage] = NodeEconomyTypes.RewardConfig({
            baseRewardPerEpoch: 0.01 ether,
            performanceMultiplierBps: 5000,
            epochDuration: globalEpochDuration,
            active: true
        });
        _rewardConfigs[NodeEconomyTypes.NodeClass.Execution] = NodeEconomyTypes.RewardConfig({
            baseRewardPerEpoch: 0.05 ether,
            performanceMultiplierBps: 7500,
            epochDuration: globalEpochDuration,
            active: true
        });
        _rewardConfigs[NodeEconomyTypes.NodeClass.Indexing] = NodeEconomyTypes.RewardConfig({
            baseRewardPerEpoch: 0.02 ether,
            performanceMultiplierBps: 5000,
            epochDuration: globalEpochDuration,
            active: true
        });
        _rewardConfigs[NodeEconomyTypes.NodeClass.Research] = NodeEconomyTypes.RewardConfig({
            baseRewardPerEpoch: 0.1 ether,
            performanceMultiplierBps: 10000,
            epochDuration: globalEpochDuration,
            active: true
        });
    }

    function setGlobalEpochDuration(uint256 duration) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(duration >= 1 days, "Epoch too short");
        require(duration <= 30 days, "Epoch too long");
        globalEpochDuration = duration;

        _rewardConfigs[NodeEconomyTypes.NodeClass.Storage].epochDuration = duration;
        _rewardConfigs[NodeEconomyTypes.NodeClass.Execution].epochDuration = duration;
        _rewardConfigs[NodeEconomyTypes.NodeClass.Indexing].epochDuration = duration;
        _rewardConfigs[NodeEconomyTypes.NodeClass.Research].epochDuration = duration;
    }

    function setMaxRewardsPerEpoch(uint256 maxRewards) external onlyRole(DEFAULT_ADMIN_ROLE) {
        maxRewardsPerEpoch = maxRewards;
    }

    function setRewardConfig(
        NodeEconomyTypes.NodeClass nodeClass,
        uint256 baseReward,
        uint256 multiplierBps
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(multiplierBps <= 20000, "Multiplier too high");

        _rewardConfigs[nodeClass] = NodeEconomyTypes.RewardConfig({
            baseRewardPerEpoch: baseReward,
            performanceMultiplierBps: multiplierBps,
            epochDuration: globalEpochDuration,
            active: true
        });

        emit RewardConfigUpdated(nodeClass, baseReward, multiplierBps);
    }

    function updatePerformance(
        uint256 nodeId,
        uint256 uptimeBps,
        uint256 tasksCompleted,
        uint256 qualityScore
    ) external onlyRole(ORACLE_ROLE) {
        require(uptimeBps <= 10000, "Invalid uptime");
        require(qualityScore <= 10000, "Invalid quality score");
        require(nodeRegistry.isNodeActive(nodeId), "Node not active");

        _nodePerformance[nodeId] = NodeEconomyTypes.PerformanceMetrics({
            uptimeBps: uptimeBps,
            tasksCompleted: tasksCompleted,
            qualityScore: qualityScore,
            lastUpdated: block.timestamp
        });

        emit PerformanceUpdated(nodeId, uptimeBps, tasksCompleted, qualityScore);
    }

    function calculateNodeReward(uint256 nodeId) public view returns (uint256) {
        NodeEconomyTypes.NodeInfo memory node = nodeRegistry.getNode(nodeId);
        if (node.status != NodeEconomyTypes.NodeStatus.Active) {
            return 0;
        }

        NodeEconomyTypes.RewardConfig memory config = _rewardConfigs[node.nodeClass];
        if (!config.active) {
            return 0;
        }

        NodeEconomyTypes.PerformanceMetrics memory perf = _nodePerformance[nodeId];

        uint256 baseReward = config.baseRewardPerEpoch;

        uint256 performanceScore = 5000;
        if (perf.lastUpdated > 0) {
            performanceScore = (perf.uptimeBps + perf.qualityScore) / 2;
        }

        uint256 multiplier = 10000 + (performanceScore * config.performanceMultiplierBps / 10000);

        return baseReward * multiplier / 10000;
    }

    function processEpochRewards() external onlyRole(REWARDS_MANAGER_ROLE) whenNotPaused {
        require(block.timestamp >= epochStartTime + globalEpochDuration, "Epoch not complete");

        _epochRewards[currentEpoch].epochId = currentEpoch;
        _epochRewards[currentEpoch].timestamp = block.timestamp;

        emit EpochCompleted(currentEpoch, _epochRewards[currentEpoch].totalRewards, _epochRewards[currentEpoch].nodesRewarded);

        currentEpoch++;
        epochStartTime = block.timestamp;
    }

    function distributeReward(uint256 nodeId) external onlyRole(REWARDS_MANAGER_ROLE) whenNotPaused nonReentrant {
        require(!_epochNodeRewarded[currentEpoch][nodeId], "Already rewarded this epoch");
        require(nodeRegistry.isNodeActive(nodeId), "Node not active");
        require(_epochRewards[currentEpoch].totalRewards < maxRewardsPerEpoch, "Epoch reward cap reached");

        uint256 reward = calculateNodeReward(nodeId);
        require(reward > 0, "No reward");

        uint256 remainingCap = maxRewardsPerEpoch - _epochRewards[currentEpoch].totalRewards;
        if (reward > remainingCap) {
            reward = remainingCap;
        }

        require(address(this).balance >= reward, "Insufficient funds");

        _pendingRewards[nodeId] += reward;
        _epochNodeRewarded[currentEpoch][nodeId] = true;

        nodeRegistry.recordReward(nodeId, reward);

        _epochRewards[currentEpoch].totalRewards += reward;
        _epochRewards[currentEpoch].nodesRewarded++;
        _epochRewards[currentEpoch].epochId = currentEpoch;
        _epochRewards[currentEpoch].timestamp = block.timestamp;
    }

    function claimRewards(uint256 nodeId) external nonReentrant whenNotPaused {
        NodeEconomyTypes.NodeInfo memory node = nodeRegistry.getNode(nodeId);
        require(node.operator == msg.sender, "Not operator");

        uint256 amount = _pendingRewards[nodeId];
        require(amount > 0, "No pending rewards");

        _pendingRewards[nodeId] = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");

        emit RewardClaimed(nodeId, msg.sender, amount);
    }

    function getPendingRewards(uint256 nodeId) external view returns (uint256) {
        return _pendingRewards[nodeId];
    }

    function getPerformanceMetrics(uint256 nodeId) external view returns (NodeEconomyTypes.PerformanceMetrics memory) {
        return _nodePerformance[nodeId];
    }

    function getCurrentEpoch() external view returns (uint256) {
        return currentEpoch;
    }

    function getEpochReward(uint256 epochId) external view returns (NodeEconomyTypes.EpochReward memory) {
        return _epochRewards[epochId];
    }

    function getRewardConfig(NodeEconomyTypes.NodeClass nodeClass) external view returns (NodeEconomyTypes.RewardConfig memory) {
        return _rewardConfigs[nodeClass];
    }

    function getTimeUntilNextEpoch() external view returns (uint256) {
        uint256 epochEnd = epochStartTime + globalEpochDuration;
        if (block.timestamp >= epochEnd) {
            return 0;
        }
        return epochEnd - block.timestamp;
    }

    function pause() external onlyRole(GUARDIAN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(GUARDIAN_ROLE) {
        _unpause();
    }

    function fundRewards() external payable {}

    receive() external payable {}
}

